// fire.mjs —— 可选的带外包装（设计文档「已签字的机制选择」：带外归老板、带外只 tick，
// OPC 提供返回契约与可选预检包装）。
// 本分的路数：
//   ① 纯脚本预检（precheck，一分钱模型钱不花）——门没过就原样返回对应状态，绝不拉会话；
//   ② 没活可干（action=none）同样不拉，按 NOTHING_TO_DO 返回；
//   ③ 纯流程轮脚本化（B）：预检判 action=acceptance 且 machine_only（该里程碑全部验收标准
//      机器可判、没有人判条目）→ fire 不拉 claude，进程内自跑完整验收轮生命周期
//      （tick-begin→acceptance-run→固定模板自动叙述→tick-end），透传对应退出码，全程零模型开销；
//   ④ 其余情况才拼出要执行的命令：claude -p '/opc:opc-tick' --model <壳模型>，
//      在项目根里拉起无界面会话跑一轮 tick，tick 的退出码原样透传给带外调度器。
// 壳会话模型可配置（设计：默认中档）：.opc/team/config.json 的 tick_model 字段，
// 经 write team-config 落盘；没配就用默认档。
// MVP 支持干跑：--dry-run 只报出将执行的命令/将走的脚本轮，不真跑——演练和带外调试都靠它先看一眼。
// 铁律：拉会话那条路不写 .opc/（预检纯读、拉会话是别人的进程）；脚本验收轮这条路要写 .opc/，
// 但一切落盘照旧只经 store（有指纹有事件），且退出码契约、带外触发语义半点不变；出错原样上抛，绝不吞。

import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { EXIT, PATHS, WRITE_TYPES } from './schemas.mjs';
import { readJson, writeJson, appendLine } from './store.mjs';
import { precheck } from './precheck.mjs';
import { acquire } from './lock.mjs';
import { runAcceptance } from './acceptance.mjs';
import { tickEnd } from './report.mjs';

// 壳会话的默认模型档：中档（它只执行预检返回的计划和派工，不需要强模型）。
const defaultShellModel = 'sonnet';

// OPC 插件目录（本仓库根，.claude-plugin/plugin.json 住在那）：拉 tick 会话时带 --plugin-dir
// 指过去，claude 才认识 /opc:opc-tick 斜杠命令。fire.mjs 在 scripts/lib/ 下，往上两级即仓库根。
// 环境变量 OPC_PLUGIN_DIR 可覆盖（打包分发或换位置时用）。
function pluginDir() {
  const override = process.env.OPC_PLUGIN_DIR;
  if (typeof override === 'string' && override.trim() !== '') return override;
  return path.resolve(fileURLToPath(new URL('.', import.meta.url)), '..', '..');
}

// 团队私有参数的存放位置以写入类型表声明的为准，不另抄路径字面量。
const teamConfigPath = WRITE_TYPES['team-config'].path();

// 真拉起器：同步拉起 claude 无界面会话，stdio 直通（tick 的汇报当场打给触发者）。
// 返回子进程退出码。claude 命令不在就白话喊停，绝不吞成一般错误。
function launchSession(command, cwd) {
  const r = spawnSync(command[0], command.slice(1), { cwd, stdio: 'inherit' });
  if (r.error) {
    if (r.error.code === 'ENOENT') {
      throw new Error('找不到 claude 命令，没法拉起 tick 会话；请确认 Claude Code 已安装并在 PATH 里');
    }
    throw r.error;
  }
  // 子进程被信号杀掉时 status 是 null——按一般性出错报，带外好歹知道这轮没善终。
  return Number.isInteger(r.status) ? r.status : EXIT.ERROR;
}

// 脚本验收轮（B 纯流程轮脚本化）：预检判 machine_only 后，fire 进程内自跑完整验收轮生命周期，
// 一分钱模型钱不花。等价于一个 tick 剧本的验收轮，只是全程没有任何 claude 会话：
//   ① tick-begin：取锁领代数与轮次（session 用 fire 自身标识、pid 用本进程），并登记派工；
//   ② acceptance-run：评判 + 结论入册 + 状态流转闭环（runAcceptance）；
//   ③ 固定模板自动叙述 + 下轮计划落草稿（叙述满足叙述校验器：≥20 字 + 「」锚点、不碰账目数字）；
//   ④ tick-end：落 tick 正式档、渲染汇报存档、放锁，把本轮结局映射成退出码原样透传。
// 一切落盘只经 store（有指纹有事件）。半路出错就原样上抛、锁留在原地（这轮没收好尾的记号，
// 和 tick 剧本同规矩——本进程随即退出，留下的锁按死锁由下一次 tick-begin 零等待接管）。
async function runMachineAcceptance(root, milestone) {
  const session = `fire-脚本验收-${milestone}`;

  // ① tick-begin：取锁（session/pid 都是 fire 自身）。抢不到活锁＝预检到此刻之间被别人抢了先，
  //    按锁被占返回、绝不硬写（预检门⑨本已挡活锁，这里兜竞态）。
  const got = await acquire(root, { session, pid: process.pid });
  if (!got.acquired) {
    const h = got.holder;
    const who = h
      ? `第 ${h.generation} 代持有者还占着（进程 ${h.holder?.pid ?? '不明'}，会话 ${h.holder?.session ?? '不明'}）`
      : '刚被别的会话抢走';
    return {
      output: { ok: false, fired: false, gate: '锁', reason: `脚本验收开工时锁被占：${who}，这轮让路` },
      exit: EXIT.LOCK_HELD
    };
  }
  const generation = got.generation;
  const seq = got.tickSeq;

  // 序号跟进状态档（与 tick-begin 一致）。
  const state = await readJson(root, PATHS.state);
  if (state === null) {
    throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，脚本验收轮没法开工`);
  }
  state.tick_seq = seq;
  await writeJson(root, PATHS.state, state, {
    actor: '脚本',
    event: `tick-begin:第 ${seq} 轮（第 ${generation} 代，脚本验收轮）`
  });

  // 登记派工：本轮由 fire 自身跑完，员工记「脚本」、会话用 fire 自身标识（记账归属齐全）。
  // 不带 model——脚本验收轮没有任何模型调用，没有用量可归。
  const dispatch = { session_id: session, employee: '脚本', tick: seq };
  WRITE_TYPES['dispatch'].validate(dispatch);
  await appendLine(root, WRITE_TYPES['dispatch'].path(), dispatch);

  // ② acceptance-run：评判 + 结论入册 + 状态流转闭环。
  const result = await runAcceptance(root, milestone, { actor: '脚本' });
  if (result.pass === null) {
    // 不该发生：预检已判 machine_only（无人判条目）。真出现待人判条目＝清单在预检与此刻之间被
    // 体外改动，喊停不猜（叙述都还没落、锁留原地）。
    throw new Error(
      `里程碑「${milestone}」验收冒出待人判条目，与预检的 machine_only 判定矛盾，` +
      '验收清单可能在预检之后被体外改动，停手等人查'
    );
  }

  // ③ 固定模板自动叙述 + 下轮计划落草稿（走 tick-field 同一套校验，坏字段进不了草稿）。
  const narrative = `脚本验收：里程碑「${milestone}」逐条机器判定，结论「${result.pass ? '通过' : '不通过'}」，全程零模型开销`;
  const nextPlan = result.pass
    ? `里程碑「${milestone}」已收官，下一轮按预检行动计划挑下一个里程碑`
    : `里程碑「${milestone}」验收未过，下一轮先落复盘记录再重拆修复 sprint`;
  const draftRel = WRITE_TYPES['tick-field'].path(seq);
  const fields = { narrative, next_plan: nextPlan };
  WRITE_TYPES['tick-field'].validate(fields);
  const existing = (await readJson(root, draftRel)) ?? {};
  await writeJson(root, draftRel, { ...existing, ...fields }, { actor: '脚本', event: 'write:tick-field（脚本验收轮）' });

  // ④ tick-end：结局按验收结果映射——熔断（连败三振）报 incident，其余（过或未过但没熔断）
  //    都是「本轮活干完了」报 done-work。退出码由 tick-end 现映射，原样透传。
  const status = result.incident ? 'incident' : 'done-work';
  const ended = await tickEnd(root, { generation, status, action: 'acceptance' });
  return {
    output: {
      ok: true,
      fired: false,
      machine_only: true,
      action: 'acceptance',
      milestone,
      pass: result.pass,
      incident: result.incident,
      tick: ended.seq,
      report: ended.reportRel,
      tick_exit: ended.exit
    },
    exit: ended.exit
  };
}

